    includeSubDomains: true,
  },
  frameguard: {
    action: 'deny'
  }
}));

// Rate limiting to prevent abuse
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // Limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Input validation and sanitization middleware
app.use((req, res, next) => {
  // Reject requests with too many query parameters (potential parameter pollution)
  if (Object.keys(req.query).length > 5) {
    return res.status(400).json({
      error: 'Invalid request - too many parameters'
    });
  }

  // Clean query parameters of potential malicious content
  Object.keys(req.query).forEach(key => {
    if (typeof req.query[key] === 'string') {
      // Basic XSS protection
      if (/<script/i.test(req.query[key])) {
        return res.status(400).json({
          error: 'Invalid request - potential XSS attack detected'
        });
      }
    }
  });

  next();
});

