const express = require('express');
const app = express();

// Security headers middleware (built-in, no dependencies)
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Rate limiting variables
  const ip = req.ip;
  const now = Date.now();

  // Simple in-memory rate limiting (not for production)
  if (!app.rateLimits) app.rateLimits = {};
  if (!app.rateLimits[ip]) app.rateLimits[ip] = { count: 0, windowStart: now };

  const rateLimit = app.rateLimits[ip];

  // Reset counter if outside of window
  if (now - rateLimit.windowStart > 15 * 60 * 1000) { // 15 minutes
    rateLimit.count = 0;
    rateLimit.windowStart = now;
  }

  // Check if rate limit exceeded
  if (rateLimit.count >= 100) { // Limit to 100 requests per window
    return res.status(429).json({
      error: 'Rate limit exceeded. Try again later.'
    });
  }

  // Increment counter
  rateLimit.count++;

  next();
});

// Input validation middleware
app.use((req, res, next) => {
  // Reject requests with too many query parameters (potential parameter pollution)
  if (Object.keys(req.query).length > 5) {
    return res.status(400).json({
      error: 'Invalid request - too many parameters'
    });
  }

  // Check for potential XSS attempts in query parameters
  Object.keys(req.query).forEach(key => {
    if (typeof req.query[key] === 'string') {
      // Look for script tags or javascript: expressions
      if (/<script|javascript:/i.test(req.query[key])) {
        return res.status(400).json({
          error: 'Invalid request - potential XSS attack detected'
        });
      }
    }
  });

  next();
});

app.get('/health', (req, res) => {
  // Validate no unexpected parameters for health check
  if (Object.keys(req.query).length > 0) {
    return res.status(400).json({
      error: 'Health check endpoint does not accept parameters'
    });
  }

  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  try {
    // In a real app, this would query a database with proper validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Handle 404 errors for undefined routes
app.use((req, res) => {
