const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: []
    }
  }
}));

// Rate limiting to prevent brute force and DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
}));

// Request parsing with size limits
app.use(express.json({
  limit: '10kb',
  verify: (req, res, buf) => {
    req.rawBody = buf;
  }
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// Timeout for slow requests
app.use((req, res, next) => {
  req.setTimeout(30000, () => {
    res.status(408).json({
      error: 'Request timeout'
    });
  });
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Health check failed'
    });
  }
});

// Users endpoint with potential ID parameter (example of input validation)
app.get('/users', (req, res) => {
  try {
    // Example of query parameter validation
    const { limit, offset } = req.query;

    // Input validation
    if (limit && (!Number.isInteger(Number(limit)) || Number(limit) <= 0 || Number(limit) > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be a positive integer less than or equal to 100.'
      });
    }

    if (offset && (!Number.isInteger(Number(offset)) || Number(offset) < 0)) {
      return res.status(400).json({
        error: 'Invalid offset parameter. Must be a non-negative integer.'
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if parameters are provided
    let result = users;
    if (limit || offset) {
      const skip = Number(offset) || 0;
      const take = Number(limit) || users.length;
      result = users.slice(skip, skip + take);
    }

    res.json(result);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  if (error.name === 'SyntaxError' && error.status === 400 && 'body' in error) {
    return res.status(400).json({
      error: 'Invalid JSON in request body'
    });
  }

  res.status(500).json({
    error: 'Something went wrong!'
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

