// Required environment variables for this service
const REQUIRED_ENV_VARS = [
  'PORT'
];

// Optional environment variables with defaults
const DEFAULT_ENV_VARS = {
  'ALLOWED_ORIGINS': '*',
  'NODE_ENV': 'development'
};

// Validate required environment variables
function validateEnv() {
  const missingVars = [];

  REQUIRED_ENV_VARS.forEach(varName => {
    if (!process.env[varName]) {
      missingVars.push(varName);
    }
  });

  if (missingVars.length > 0) {
    console.error('Missing required environment variables:', missingVars);
    console.error('Please set these variables before starting the application');
    process.exit(1);
  }
}

// Apply default values for optional variables
function applyDefaults() {
  Object.entries(DEFAULT_ENV_VARS).forEach(([key, defaultValue]) => {
    if (!process.env[key]) {
      process.env[key] = defaultValue;
    }
  });
}

// Initialize configuration
function initConfig() {
  applyDefaults();
  validateEnv();

  return {
    port: parseInt(process.env.PORT, 10),
    allowedOrigins: process.env.ALLOWED_ORIGINS,
    isProduction: process.env.NODE_ENV === 'production'
  };
