```javascript
// Security middleware and utilities
const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const { body, query, validationResult } = require('express-validator');
const logger = require('./logger');

// Security configuration
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

const app = express();

// Security middleware - should be early in the stack
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Request size limiting
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Apply rate limiting
app.use(limiter);

// Input sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Clean query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        // Basic XSS protection
        req.query[key] = req.query[key].replace(/[<>]/g, '');
      }
    });
  }
  next();
};

app.use(sanitizeInput);

// Enhanced health check with proper error handling
app.get('/health', 
  [
    // Input validation for health check
    query('detailed').optional().isBoolean().withMessage('Detailed must be boolean'),
  ],
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn(`Health check validation failed: ${errors.array()[0].msg}`, {
          ip: req.ip,
          userAgent: req.get('User-Agent')
        });
        return res.status(400).json({ 
