const express = require('express');
const app = express();

// Security: Set security headers manually
app.use((req, res, next) => {
  // Basic security headers (similar to helmet)
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Limit request size to prevent abuse
  if (req.get('Content-Length')) {
    const length = parseInt(req.get('Content-Length'));
    if (length > 1024 * 1024) { // 1MB limit
      return res.status(413).json({
        error: 'Payload too large',
        message: 'Request body too large'
      });
    }
  }

  next();
});

// Enhanced JSON parsing with size limiting
app.use(express.json({
  limit: '1mb',
  verify: (req, res, buf) => {
    // Additional validation can be added here
    if (buf.length > 1024 * 1024) {
      throw new Error('Body too large');
    }
  }
}));

// Rate limiting simulation (simple in-memory implementation)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100; // Max requests per window

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();
  const key = `${ip}:${req.path}`;

  // Clean old entries
  if (requestCounts.size > 1000) {
    // Simple cleanup to prevent memory growth
    const cleanKey = Array.from(requestCounts.keys())[0];
    requestCounts.delete(cleanKey);
  }

  const record = requestCounts.get(key) || { count: 0, firstRequest: now };

  // Check if window has expired
  if (now - record.firstRequest > RATE_LIMIT_WINDOW_MS) {
    record.count = 1;
    record.firstRequest = now;
  } else {
    record.count++;
  }

  requestCounts.set(key, record);

  // Check rate limit
  if (record.count > MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: Math.ceil((RATE_LIMIT_WINDOW_MS - (now - record.firstRequest)) / 1000)
    });
  }

  next();
});

// Input validation middleware for parameters
const validateIdParam = (req, res, next) => {
  const id = req.params.id;
  if (!id) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'ID parameter is required'
    });
  }

  // Basic validation - check if it's a positive integer
  const idNum = parseInt(id, 10);
  if (isNaN(idNum) || idNum <= 0 || !/^[0-9]+$/.test(id)) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'ID must be a positive integer'
    });
  }

  // Store validated ID in request for downstream handlers
  req.validated = req.validated || {};
  req.validated.id = idNum;

  next();
};

// Health check with proper error handling
app.get('/health', (req, res) => {
  try {
    // In a real app, you might check database connectivity, etc.
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // This should not happen in this simple route, but good practice
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Health check failed'
    });
  }
});

// Users endpoint with validation
app.get('/users', (req, res) => {
  try {
    // Sample data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Handle query parameters for filtering/pagination
    let filteredUsers = [...users];

    // Simple search by name
    if (req.query.name) {
      const nameQuery = String(req.query.name).trim();

      // Validate query parameter length
      if (nameQuery.length > 50) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Name query parameter is too long'
        });
      }

      // Sanitize input and perform case-insensitive search
      const safeNameQuery = nameQuery.replace(/[<>"'&]/g, '');
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(safeNameQuery.toLowerCase())
      );
    }

    // Add pagination support
    const page = req.query.page ? parseInt(req.query.page) : 1;
    const limit = req.query.limit ? parseInt(req.query.limit) : 10;

    // Validate pagination parameters
    if (isNaN(page) || page < 1) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Page parameter must be a positive integer'
      });
    }

    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Limit parameter must be between 1 and 100'
      });
    }

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Return response with metadata
    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        pages: Math.ceil(filteredUsers.length / limit),
        hasPrevious: page > 1,
        hasNext: endIndex < filteredUsers.length
      }
    });

  } catch (error) {
    console.error('Error in /users route:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred'
    });
  }
});

// Route for getting a specific user
app.get('/users/:id', validateIdParam, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === req.validated.id);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `User with ID ${req.validated.id} not found`
      });
    }

    res.json(user);

  } catch (error) {
    console.error(`Error fetching user ${req.validated.id}:`, error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Determine status code
  const statusCode = error.statusCode || error.status || 500;

  // Never expose error details in production
  const response = {
    error: statusCode === 500 ? 'Internal Server Error' : error.message || 'An error occurred',
    message: statusCode === 500 
      ? 'An unexpected error occurred'
      : error.message || 'An error occurred'
  };

  // Add stack trace only in development
  if (process.env.NODE_ENV === 'development' && statusCode !== 500) {
    response.stack = error.stack;
  }

  res.status(statusCode).json(response);
});

// Server configuration
