/**
 * Centralized error handling middleware
 */

// Custom error classes
class ValidationError extends Error {
  constructor(message, details = null) {
    super(message);
    this.name = 'ValidationError';
    this.status = 400;
    this.details = details;
  }
}

class UnauthorizedError extends Error {
  constructor(message = 'Unauthorized') {
    super(message);
    this.name = 'UnauthorizedError';
    this.status = 401;
  }
}

class ForbiddenError extends Error {
  constructor(message = 'Forbidden') {
    super(message);
    this.name = 'ForbiddenError';
    this.status = 403;
  }
}

class NotFoundError extends Error {
  constructor(message = 'Not Found') {
    super(message);
    this.name = 'NotFoundError';
    this.status = 404;
  }
}

// Global error handler middleware
const errorHandler = (err, req, res, next) => {
  // Log error (in production, you might want to use a logging service)
  console.error('Error details:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });

  // Set default status code
  const statusCode = err.status || 500;

  // Don't leak sensitive error details in production
  const isProd = process.env.NODE_ENV === 'production';

  // Prepare response
  const errorResponse = {
    error: {
      message: isProd && statusCode === 500 
        ? 'Internal server error' 
        : err.message,
      ...(err.name && { name: err.name }),
      ...(err.details && { details: err.details })
    }
  };

  // Add request ID if available (useful for correlation in logs)
  if (req.id) {
    errorResponse.error.requestId = req.id;
  }

  // Add validation error details for 400 errors (but don't expose in prod)
  if (err instanceof ValidationError && (!isProd || statusCode !== 500)) {
    errorResponse.error.details = err.details;
  }

  res.status(statusCode).json(errorResponse);
};

module.exports = {
  errorHandler,
  ValidationError,
  UnauthorizedError,
  ForbiddenError,
  NotFoundError
};

