  // Basic security headers
  contentSecurityPolicy: {
    useDefaults: true,
    directives: {
      'script-src': ["'self'", "'unsafe-inline'", "'unsafe-eval'"] // Only allow scripts from same origin
    }
  },
  // XSS protection
  xssFilter: true,
  // Prevent clickjacking
  frameguard: { action: 'deny' },
  // Hide powered-by header
  hidePoweredBy: { setTo: 'PHP 4.2.0' }, // Obfuscate server technology
  // No MIME type sniffing
  noSniff: true,
  // Disable caching by default (can be overridden per route)
  noCache: false
});

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: {
    error: {
      message: 'Too many requests from this IP, please try again later.'
    }
  },
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Request size limiting to prevent DOS
const jsonLimit = express.json({ limit: '10kb' });
const urlencodedLimit = express.urlencoded({ extended: true, limit: '10kb' });

// Request timeout
const requestTimeout = (req, res, next) => {
  req.setTimeout(30000, () => { // 30 seconds
    res.status(408).json({ 
      error: { 
        message: 'Request timeout' 
      } 
    });
  });
  next();
};

// Input sanitization (basic example)
const sanitizeInput = (req, res, next) => {
  // Clean query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        // Remove potential SQL injection patterns
        req.query[key] = req.query[key]
          .replace(/('|--|%;|\)/g, '')
          .trim();
      }
    });
  }

  // Clean body parameters
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        // Remove potential XSS injection patterns
        req.body[key] = req.body[key]
          .replace(/(<script|javascript:|on\w+=)/gi, '')
          .trim();
      }
    });
  }

  next();
};

module.exports = {
  securityHeaders,
  limiter,
  jsonLimit,
  urlencodedLimit,
  requestTimeout,
  sanitizeInput
};

