const express = require('express');

// Import security and error handling modules
const { securityHeaders, limiter, jsonLimit, urlencodedLimit, requestTimeout, sanitizeInput } = require('./security');
const { errorHandler, ValidationError } = require('./error-handler');

const app = express();

// Apply security middleware
app.use(securityHeaders);
app.use(limiter);
app.use(jsonLimit);
app.use(urlencodedLimit);
app.use(requestTimeout);
app.use(sanitizeInput);

// Health check endpoint
app.get('/health', (req, res, next) => {
  try {
    // Simulate potential error for testing error handling
    if (req.query.fail) {
      throw new Error('Simulated health check failure');
    }

    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    // Pass error to global error handler
    next(error);
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Input validation
    const { page, limit, sort } = req.query;

    // Validate query parameters
    if (page && (!Number.isInteger(Number(page)) || Number(page) < 1)) {
      return next(new ValidationError('Page must be a positive integer'));
    }

    if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
      return next(new ValidationError('Limit must be an integer between 1 and 100'));
    }

    if (sort && !['name', 'email', 'id'].includes(sort)) {
      return next(new ValidationError('Sort field must be one of: name, email, id'));
    }

    // In a real app, this data would come from a database with proper access controls
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if requested
    const pageNum = page ? Number(page) : 1;
    const limitNum = limit ? Number(limit) : users.length;
    const startIndex = (pageNum - 1) * limitNum;
    const paginatedUsers = users.slice(startIndex, startIndex + limitNum);

    // Apply sorting if requested
    if (sort) {
      paginatedUsers.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });
    }

    res.json({
      data: paginatedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: users.length,
        pages: Math.ceil(users.length / limitNum)
      }
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use('*', (req, res, next) => {
  const error = new Error(`Route ${req.method} ${req.url} not found`);
  error.status = 404;
  next(error);
});

// Apply global error handling middleware (must be last)
app.use(errorHandler);

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

