app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting (basic implementation - consider express-rate-limit for production)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100; // Per IP

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Clean old entries
  if (requestCounts.size > 1000) { // Prevent memory bloat
    for (const [key, value] of requestCounts) {
      if (now - value.timestamp > RATE_LIMIT_WINDOW_MS) {
        requestCounts.delete(key);
      }
    }
  }

  const record = requestCounts.get(ip) || { count: 0, timestamp: now };

  if (now - record.timestamp > RATE_LIMIT_WINDOW_MS) {
    // Reset counter if outside window
    record.count = 1;
    record.timestamp = now;
  } else {
    record.count++;
  }

  requestCounts.set(ip, record);

  if (record.count > MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.'
    });
  }

  next();
});

// Health check with proper error handling
app.get('/health', (req, res) => {
  try {
    // Add additional health checks here if needed
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Health check failed',
      message: 'Internal server error'
    });
  }
});

