const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const app = express();

// Security middleware
app.use(helmet());
app.use(helmet.permittedCrossDomainPolicies());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Prevent SQL injection, XSS, and other injection attacks
  for (const [key, value] of Object.entries(req.query)) {
    if (typeof value === 'string') {
      // Basic SQL injection prevention
      const sqlPattern = /(\s+OR\s+|'|"|;|--|\/\*|\*\/|\b(ALTER|CREATE|DELETE|DROP|EXEC(UTE)?|INSERT|MERGE|SELECT|UPDATE|UNION(\s+ALL)?)\b)/gi;
      if (sqlPattern.test(value)) {
        return res.status(400).json({
          error: 'Invalid parameter detected',
          message: 'Request contains potentially malicious input'
        });
      }

      // Basic XSS prevention
      const xssPattern = /(<script|<img|<svg|<iframe|javascript:|on\w+\s*=|data:text\/+)/gi;
      if (xssPattern.test(value)) {
        return res.status(400).json({
          error: 'Invalid parameter detected',
          message: 'Request contains potentially malicious input'
        });
      }
    }
  }
  next();
};

// Enhanced error handling middleware
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err.stack);
  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

// Rate limiting inspired middleware (basic implementation)
const requestCounts = {};
const RATE_LIMIT = 100; // requests
const RATE_WINDOW = 15 * 60 * 1000; // 15 minutes

app.use((req, res, next) => {
  const clientIP = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  if (!requestCounts[clientIP]) {
    requestCounts[clientIP] = [];
  }

  // Remove timestamps outside the window
  requestCounts[clientIP] = requestCounts[clientIP].filter(
    timestamp => timestamp > now - RATE_WINDOW
  );

  if (requestCounts[clientIP].length >= RATE_LIMIT) {
    return res.status(429).json({
      error: 'Rate limit exceeded',
      message: 'Too many requests, please try again later'
    });
  }

  requestCounts[clientIP].push(now);
  next();
});

app.use(validateQueryParams);

