  // Simple rate limiting storage (in production, use Redis or similar)
  if (!app.rateLimitStore) {
    app.rateLimitStore = new Map();
  }

  const clientStore = app.rateLimitStore.get(clientIp) || {
    count: 0,
    resetTime: now + windowMs
  };

  // Reset counter if window has passed
  if (now > clientStore.resetTime) {
    clientStore.count = 0;
    clientStore.resetTime = now + windowMs;
  }

  // Check if rate limit exceeded
  if (clientStore.count >= 100) { // limit to 100 requests per window
    return res.status(429).json({
      error: 'Too many requests from this IP, please try again later.'
    });
  }

  // Increment counter
