const createError = require('http-errors');

// Basic input validation middleware
const validateUserInput = (req, res, next) => {
  const { name, email } = req.body;

  if (!name || !email) {
    return next(createError(400, 'Name and email are required'));
  }

  // Basic email validation
  const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;
  if (!emailRegex.test(email)) {
    return next(createError(400, 'Invalid email format'));
  }

  // Basic name validation (prevent obviously malicious input)
  if (name.length < 2 || name.length > 100) {
    return next(createError(400, 'Name must be between 2 and 100 characters'));
  }

  next();
};

module.exports = { validateUserInput };

const isProd = process.env.NODE_ENV === 'production';

const errorHandler = (err, req, res, next) => {
  // Log the error (in production, you'd send this to a logging service)
  console.error(err.stack);

  // Set locals, only providing error in development
  res.locals.message = err.message;
  res.locals.error = isProd ? {} : err;

  // Set response status (use err.status or default to 500)
  const status = err.status || 500;
  res.status(status);

  // Return JSON response for API routes
  if (req.originalUrl.startsWith('/api/') || req.xhr) {
    return res.json({
      error: {
        message: err.message,
        ...(isProd ? {} : { stack: err.stack }),
      }
    });
  }

  // Render an error page for regular requests (not applicable for this API)
  res.json({
    error: {
      message: err.message,
      status: status,
      ...(isProd ? {} : { stack: err.stack }),
    }
  });
};

module.exports = errorHandler;

/**
 * Sanitize user input to prevent XSS and other injection attacks
 */
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;

  // Remove potentially dangerous characters/sequences
  return input
    .replace(/<(script|img|iframe|object|embed|link|style)/gi, '&lt;$1')
    .replace(/javascript:/gi, 'javascript&amp;colon;')
    .replace(/vbscript:/gi, 'vbscript&amp;colon;')
    .replace(/data:/gi, 'data&amp;colon;')
    .replace(/\u0000/g, '') // Remove null bytes
    .trim();
};

const sanitizeUser = (user) => {
  if (!user) return user;

  const sanitized = { ...user };

  if (sanitized.name) {
    sanitized.name = sanitizeInput(sanitized.name);
  }
  if (sanitized.email) {
    sanitized.email = sanitizeInput(sanitized.email);
  }

  return sanitized;
};

module.exports = { sanitizeInput, sanitizeUser };

