const express = require('express');
const helmet = require('helmet');
const cors = require('cors');

// Middleware
const errorHandler = require('./middleware/errorHandler');
const { validateUserInput } = require('./middleware/validation');
const { sanitizeUser } = require('./utils/sanitize');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(helmet.permittedCrossDomainPolicies()); // Additional helmet security

// Enable CORS with strict configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
}));

// Body parsing with limits to prevent abuse
app.use(express.json({
  limit: '10kb',
  verify: (req, res, buf) => {
    req.rawBody = buf;
  }
}));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Rate limiting (basic implementation - in production, use express-rate-limit)
const requestCounts = new Map();
const windowMs = parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 900000; // 15 minutes
const maxRequests = parseInt(process.env.RATE_LIMIT_MAX) || 100;

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();
  const requests = requestCounts.get(ip) || { count: 0, timestamp: now };

  // Reset counter if outside the rate limit window
  if (now - requests.timestamp > windowMs) {
    requests.count = 0;
    requests.timestamp = now;
  }

  requests.count++;
  requestCounts.set(ip, requests);

  // Set rate limit headers
  res.setHeader('X-RateLimit-Limit', maxRequests);
  res.setHeader('X-RateLimit-Remaining', Math.max(0, maxRequests - requests.count));

  if (requests.count > maxRequests) {
    return res.status(429).json({
      error: 'Rate limit exceeded. Please try again later.',
      retryAfter: requests.timestamp + windowMs
    });
  }

  next();
});

// Health check - no authentication needed
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint
app.get('/users', (req, res, next) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize response data
    const sanitizedUsers = users.map(sanitizeUser);

    // Add security headers to response
    res.setHeader('Cache-Control', 'no-store');
    res.setHeader('Pragma', 'no-cache');

    res.json(sanitizedUsers);
  } catch (err) {
    next(err);
  }
});

// Example POST endpoint with validation (not in original, but good practice demonstration)
app.post('/users', validateUserInput, (req, res, next) => {
  try {
    // In a real app, you would save to database here
    const user = {
      id: Date.now(), // This would be database generated in real app
      name: req.body.name,
      email: req.body.email
    };

    // Sanitize before sending response
    const sanitizedUser = sanitizeUser(user);

    res.status(201).json(sanitizedUser);
  } catch (err) {
    next(err);
  }
});

// Catch 404 and forward to error handler
app.use('*', (req, res, next) => {
  const err = new Error(`Route ${req.originalUrl} not found`);
  err.status = 404;
  next(err);
});

// Error handling middleware (should be last)
app.use(errorHandler);

const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server running on port ${port}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

