const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet());
app.use(helmet.permittedCrossDomainPolicies()); // Additional security

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limit to all requests
app.use(limiter);

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
};
app.use(cors(corsOptions));

// Body parsing with size limits
app.use(express.json({
  limit: '10kb', // Prevent large payload attacks
  verify: (req, res, buf) => {
    req.rawBody = buf;
  }
}));

// Security headers
app.use((req, res, next) => {
  // Prevent caching of sensitive data
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('Pragma', 'no-cache');
  next();
});

// Request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Input validation middleware (can be extended)
const validateParams = (req, res, next) => {
  // Clean query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      // Basic SQL injection prevention
      if (typeof req.query[key] === 'string' && 
          (req.query[key].includes(';') || 
           req.query[key].includes('--') || 
           req.query[key].match(/(union|select|insert|update|delete|drop|alter)\s+/i))) {
        return res.status(400).json({ error: 'Invalid parameters' });
      }
    });
  }
  next();
};

// Apply validation to all routes
app.use(validateParams);

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Health check failed',
      timestamp: new Date().toISOString() 
    });
  }
});

// Users endpoint with optional filtering
app.get('/users', (req, res) => {
  try {
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Optional filtering by name
    if (req.query.name) {
      const nameFilter = req.query.name.toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(nameFilter)
      );
    }

    // Prevent data exposure in query parameters
    if (req.query.expose === 'all') {
      return res.status(403).json({ error: 'Forbidden' });
    }

    res.json(users);

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString() 
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  res.status(error.status || 500).json({
    error: error.message || 'Internal server error',
    timestamp: new Date().toISOString()
  });
});

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

