const awsKey = process.env.AWS_ACCESS_KEY_ID;
const stripeKey = process.env.STRIPE_SECRET_KEY;
const logfireToken = process.env.LOGFIRE_TOKEN;

async function testDatabaseConnection() {
  console.log('Testing database connection...');

  try {
    // Only proceed if we have a DB URL
    if (!dbUrl) {
      console.log('❌ No DATABASE_URL provided');
      return false;
    }

    // NEVER test connections to production databases from untrusted environments
    if (dbUrl.includes('production') || dbUrl.includes('db.internal')) {
