const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Set security headers

// Configure CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Request parsing with size limits
app.use(express.json({
  limit: '10kb' // Limit request body size
}));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Validate and sanitize environment variables
const PORT = parseInt(process.env.PORT || '3000', 10);
if (isNaN(PORT) || PORT < 1 || PORT > 65535) {
  console.error('Invalid port configuration');
  process.exit(1);
}

// Health check endpoint with proper error handling
app.get('/health', [
  // Input validation
  (req, res, next) => {
    // Simple query parameter validation
    if (req.query.verbose && req.query.verbose !== 'true' && req.query.verbose !== 'false') {
      return res.status(400).json({
        error: 'Invalid query parameter: verbose must be "true" or "false"'
      });
    }
    next();
  }
], (req, res) => {
  try {
    const response = { status: 'ok', timestamp: new Date().toISOString() };

    if (req.query.verbose === 'true') {
      response.environment = process.env.NODE_ENV || 'development';
    }

    res.json(response);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error during health check'
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', [
  // Input validation middleware
  (req, res, next) => {
    // Validate query parameters
    const page = req.query.page ? parseInt(req.query.page, 10) : 1;
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;

    if (isNaN(page) || page < 1) {
      return res.status(400).json({
        error: 'Invalid page parameter: must be a positive integer'
      });
    }

    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter: must be between 1 and 100'
      });
    }

    // Attach validated values to request object
    req.validatedQuery = { page, limit };
    next();
  }
], (req, res) => {
  try {
    // Static user data (in a real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination
    const { page, limit } = req.validatedQuery;
    const startIndex = (page - 1) * limit;
    const paginatedUsers = users.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        pages: Math.ceil(users.length / limit)
      }
    });

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error while retrieving users'
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Distinguish between operational errors and programming errors
  if (error instanceof SyntaxError && error.status === 400 && 'body' in error) {
    return res.status(400).json({
      error: 'Invalid JSON in request body'
    });
  }

  res.status(500).json({
    error: 'Something went wrong!'
  });
});

// Start server
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  } else {
    console.error('Server error:', error);
  }
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

module.exports = app;

