const express = require('express');
const app = express();

// Security headers middleware (lightweight version without helmet package)
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Limit request size to prevent abuse
  if (req.get('Content-Length')) {
    const contentLength = parseInt(req.get('Content-Length'));
    if (contentLength > 10240) { // 10kb limit
      return res.status(413).json({
        error: 'Payload too large',
        timestamp: new Date().toISOString()
      });
    }
  }

  next();
});

// Request body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url}`);
  next();
});

// Simple rate limiting (in-memory, for production use a proper solution with Redis)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const RATE_LIMIT_MAX = 100; // requests per window

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Clean old entries
  if (requestCounts.size > 1000) {
    // This is a simple cleanup - in production, use a more sophisticated approach
    for (let [key, value] of requestCounts) {
      if (now - value.timestamp > RATE_LIMIT_WINDOW) {
        requestCounts.delete(key);
      }
    }
  }

  // Check rate limit
  const requestRecord = requestCounts.get(ip) || { count: 0, timestamp: now };

  if (now - requestRecord.timestamp > RATE_LIMIT_WINDOW) {
    // Reset counter if outside window
    requestRecord.count = 1;
    requestRecord.timestamp = now;
  } else {
    // Increment counter
    requestRecord.count++;
  }

  requestCounts.set(ip, requestRecord);

  if (requestRecord.count > RATE_LIMIT_MAX) {
    return res.status(429).json({
      error: 'Too many requests from this IP, please try again later',
      timestamp: new Date().toISOString()
    });
  }

  next();
});

// Input sanitization functions (lightweight without external packages)
function sanitizeInput(input) {
  if (typeof input !== 'string') return input;

  // Prevent basic XSS attempts
  return input
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

// Clean object values
function sanitizeObject(obj) {
  if (typeof obj !== 'object' || obj === null) return obj;

  const sanitized = Array.isArray(obj) ? [] : {};

  for (let key in obj) {
    if (obj.hasOwnProperty(key)) {
      if (typeof obj[key] === 'string') {
        sanitized[key] = sanitizeInput(obj[key]);
      } else if (typeof obj[key] === 'object' && obj[key] !== null) {
        sanitized[key] = sanitizeObject(obj[key]);
      } else {
        sanitized[key] = obj[key];
      }
    }
  }

  return sanitized;
}

// Prevent MongoDB operator injection (basic)
function sanitizeMongoQuery(query) {
  const dangerousOps = ['$ne', '$gt', '$lt', '$regex', '$where', '$expr', '$mod', '$exists'];

  if (typeof query !== 'object' || query === null) return query;

  const cleanQuery = Array.isArray(query) ? [] : {};

  for (let key in query) {
    if (query.hasOwnProperty(key)) {
      // Check if key is a MongoDB operator
      if (dangerousOps.includes(key)) {
        throw new Error(`Invalid query parameter: ${key}`);
      }

      if (typeof query[key] === 'object' && query[key] !== null) {
        cleanQuery[key] = sanitizeMongoQuery(query[key]);
      } else {
        cleanQuery[key] = query[key];
      }
    }
  }

  return cleanQuery;
}

