const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "*.amazonaws.com"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Body parsing with limits
app.use(express.json({
  limit: '10kb',
  strict: true
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// Enhanced health check with error handling
app.get('/health', [
  // Input validation
  body('verbose').optional().isBoolean().toBoolean()
], (req, res) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid request parameters',
        details: errors.array() 
      });
    }

    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      nodeEnv: process.env.NODE_ENV || 'development'
    };

    // Optional verbose information
    if (req.query.verbose === 'true') {
      healthData.memory = process.memoryUsage();
      healthData.platform = process.platform;
      healthData.version = process.version;
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString() 
    });
  }
});

// Users endpoint with input validation
app.get('/users', [
  // Validate query parameters
  body('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  body('offset').optional().isInt({ min: 0 }).toInt(),
  body('filter').optional().isString().trim().escape()
], (req, res) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid request parameters',
        details: errors.array() 
      });
    }

    // Simulated database users
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filtering if provided
    let filteredUsers = allUsers;
    if (req.query.filter) {
      const filter = req.query.filter.toLowerCase();
      filteredUsers = allUsers.filter(user => 
        user.name.toLowerCase().includes(filter) || 
        user.email.toLowerCase().includes(filter)
      );
    }

    // Apply pagination
    const limit = req.query.limit ? parseInt(req.query.limit) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset) : 0;
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      total: filteredUsers.length,
      limit: limit,
      offset: offset,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString() 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl,
    method: req.method,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Handle specific error types
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation failed',
      message: error.message,
      timestamp: new Date().toISOString()
    });
  }

  // Default to 500 for unhandled errors
  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred',
    timestamp: new Date().toISOString()
  });
});

// Graceful shutdown
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Close server and exit process
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// For testing purposes
module.exports = { app, server };

