## Step 4: Enhanced Error Handling Implementation

Create a more comprehensive error handling system by creating a new file `middleware/errorHandler.js`:

```javascript
const winston = require('winston');

// Create logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// If we're not in production, log to console as well
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

const errorHandler = (err, req, res, next) => {
  logger.error(`${err.status || 500} - ${err.message} - ${req.originalUrl} - ${req.method} - ${req.ip}`);

  res.status(err.status || 500).json({
    error: {
      message: process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message,
      stack: process.env.NODE_ENV === 'production' ? '🥞' : err.stack
    }
  });
};

module.exports = errorHandler;
```

## Step 5: Input Validation Middleware

Create `middleware/validation.js` for reusable validation:

```javascript
const { query, body, validationResult } = require('express-validator');

// Validate health check query parameters
const healthQueryValidation = [
  query().custom((value, { req }) => {
    const allowedParams = [];
    const invalidParams = Object.keys(req.query).filter(param => !allowedParams.includes(param));

    if (invalidParams.length > 0) {
      throw new Error(`Query parameter '${invalidParams[0]}' not allowed`);
    }

    if (Object.keys(req.query).length > 5) {
      throw new Error('Too many query parameters');
    }

    return true;
  })
];

// Validate users endpoint query parameters
const usersQueryValidation = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be a number between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  query('sort')
    .optional()
    .isIn(['name', 'id', 'email'])
    .withMessage('Sort must be one of: name, id, email')
];

// Validation result handler
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

module.exports = {
  healthQueryValidation,
  usersQueryValidation,
  validate
};
```

