# Security and Error Handling Improvements for app.js

## Critical Issues Identified

1. **No input validation** - The application accepts any input without validation or sanitization
2. **Limited error handling** - No proper error middleware or error handling mechanisms
3. **Security vulnerabilities** - Missing security headers, rate limiting, and other protections
4. **Information disclosure** - Server details are exposed
5. **No request size limits** - Vulnerable to denial of service attacks

## Recommended Improvements

### 1. Install Required Dependencies
```bash
npm install helmet express-rate-limit xss-clean express-mongo-sanitize joi
donnpm install --save-dev dotenv
```

### 2. Enhanced app.js with Security and Error Handling

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet()); // Security headers

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

app.use('/api/', limiter);

// Data sanitization
app.use(mongoSanitize()); // NoSQL injection protection
app.use(xss()); // XSS protection

// Body parser with limit
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size

// Input validation schema for consistency (if you add POST/PUT routes later)
const validateInput = (schema) => {
  return (req, res, next) => {
    const { error } = schema.validate(req.body);
    if (error) {
      return res.status(400).json({
        status: 'error',
        message: error.details[0].message.replace(/\"/g, ''),
      });
    }
    next();
  };
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    if (Object.keys(req.query).length > 0) {
      const querySchema = Joi.object({
        // Define allowed query parameters here
      }).options({ abortEarly: false });

      const { error } = querySchema.validate(req.query);
      if (error) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid query parameters',
        });
      }
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    if (Object.keys(req.query).length > 0) {
      const querySchema = Joi.object({
        limit: Joi.number().integer().min(1).max(100),
        offset: Joi.number().integer().min(0),
        sort: Joi.string().valid('name', 'email', 'id')
      }).options({ abortEarly: false });

      const { error } = querySchema.validate(req.query);
      if (error) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid query parameters',
        });
      }
    }

    // Simulated users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply query parameter logic if needed
    let filteredUsers = users;

    if (req.query.limit) {
      const limit = parseInt(req.query.limit);
      filteredUsers = filteredUsers.slice(0, limit);
    }

    if (req.query.offset) {
      const offset = parseInt(req.query.offset);
      filteredUsers = filteredUsers.slice(offset);
    }

    if (req.query.sort) {
      filteredUsers.sort((a, b) => {
        if (a[req.query.sort] < b[req.query.sort]) return -1;
        if (a[req.query.sort] > b[req.query.sort]) return 1;
        return 0;
      });
    }

    res.json(filteredUsers);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found'
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  const statusCode = error.statusCode || 500;
  const message = statusCode === 500 
    ? 'Internal server error' 
    : error.message;

  res.status(statusCode).json({
    status: 'error',
    message: message
  });
});

// Use environment variable for port, with fallback
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled rejection:', err);
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
  server.close(() => process.exit(1));
});

module.exports = app;
```

### 3. Create .env file
```
PORT=3000
NODE_ENV=development
```

### 4. Update package.json (add scripts)
```json
"scripts": {
  "start": "node app.js",
  "dev": "nodemon app.js"
}
```

## Summary of Key Security Improvements

1. **Helmet**: Adds various HTTP headers for security
2. **Rate limiting**: Prevents brute force and denial of service attacks
3. **Input sanitization**: Protects against XSS and NoSQL injection
4. **Input validation**: Ensures data integrity with Joi validation
5. **Error handling**: Centralized error handling with proper status codes
6. **Request size limits**: Prevents large payload attacks
7. **Environment variables**: Secure configuration management
8. **Comprehensive logging**: Proper error logging without exposing sensitive info
9. **404 handling**: Proper handling of undefined routes
10. **Process error handling**: Graceful shutdown on unhandled errors

These improvements significantly enhance the security posture and reliability of the application while maintaining its core functionality.

