const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Protect against well-known vulnerabilities
app.use(helmet.hidePoweredBy()); // Remove X-Powered-By header

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// CORS configuration - restrict to known origins in production
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*', // Configure in production
}));

// Input parsing with size limits to prevent abuse
app.use(express.json({
  limit: '10kb', // Limit request body size
  strict: true, // Only parse arrays and objects
}));

app.use(express.urlencoded({
  extended: false, // Use built-in query parser
  limit: '10kb',
}));

// Request logging middleware (simple version)
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with potential for ID parameter
app.get('/users', (req, res) => {
  // Validate query parameters if present
  if (req.query.id !== undefined) {
    // If we supported filtering by ID, we would validate here
    const id = Number(req.query.id);
    if (isNaN(id) || id <= 0 || !Number.isInteger(id)) {
      return res.status(400).json({
        error: 'Invalid user ID. Must be a positive integer.',
      });
    }
    // In a real app, you would filter users by ID here
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`,
  });
});

// Generic error handling middleware
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err.stack);

  // Don't leak error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error'
    : err.message || 'Internal server error';

  res.status(err.status || 500).json({
    error: message,
  });
});

// Graceful shutdown handling
const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle termination signals
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, closing server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

