  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Enable XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Remove powered by header
  res.removeHeader('X-Powered-By');

  // Content Security Policy (basic)
  res.setHeader('Content-Security-Policy', "default-src 'self'; frame-ancestors 'none'; form-action 'self'");

  next();
});

// Simple rate limiting (mimicking express-rate-limit)
const requestCounts = new Map();
const WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

app.use((req, res, next) => {
  const clientIp = req.ip;
  const now = Date.now();

  // Clean up old entries
  for (const [ip, timestamps] of requestCounts) {
    requestCounts.set(ip, timestamps.filter(ts => now - ts < WINDOW_MS));
    if (requestCounts.get(ip).length === 0) {
      requestCounts.delete(ip);
    }
  }

  // Check request count
  const requestTimes = requestCounts.get(clientIp) || [];
  if (requestTimes.length >= MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Too many requests from this IP, please try again later.'
    });
  }

  // Add current request time
  requestTimes.push(now);
  requestCounts.set(clientIp, requestTimes);

  next();
});

// Input parsing with size limits
