  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Enhanced health check with basic authentication option
app.get('/health', (req, res) => {
  try {
    // Basic health check with optional auth token validation
    const authHeader = req.get('Authorization');

    // If auth header exists, validate it
    if (authHeader) {
      // This is a simple example - in production use proper JWT or API key validation
      if (authHeader !== `Bearer ${process.env.HEALTH_CHECK_TOKEN}`) {
        logger.warn('Unauthorized health check attempt');
        return res.status(401).json({ 
          error: 'Unauthorized', 
          message: 'Invalid authorization token' 
        });
      }
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || '1.0.0'
    });
  } catch (error) {
    logger.error('Health check failed:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Health check processing failed' 
    });
  }
});

// Users endpoint with query validation
app.get('/users', (req, res) => {
  try {
    // Input validation
    const { limit, offset, name } = req.query;

    // Validate query parameters
    if (limit && (!isFinite(limit) || parseInt(limit) < 1 || parseInt(limit) > 100)) {
      return res.status(400).json({ 
        error: 'Bad Request',
        message: 'Limit must be a number between 1 and 100' 
      });
    }

    if (offset && (!isFinite(offset) || parseInt(offset) < 0)) {
      return res.status(400).json({ 
        error: 'Bad Request',
        message: 'Offset must be a non-negative number' 
      });
    }

    // Mock user data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by name if provided
    if (name) {
      const nameStr = String(name).trim().toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(nameStr)
      );
    }

    // Apply pagination
    const limitNum = limit ? parseInt(limit) : users.length;
    const offsetNum = offset ? parseInt(offset) : 0;

    const paginatedUsers = users.slice(offsetNum, offsetNum + limitNum);

    // Return additional metadata for pagination
    res.json({
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit: limitNum,
        offset: offsetNum,
        page: offsetNum ? Math.floor(offsetNum / limitNum) + 1 : 1
      }
    });

    logger.info(`Users endpoint accessed - found ${paginatedUsers.length} users`);

  } catch (error) {
    logger.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Failed to retrieve users' 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  logger.warn(`404 - Route not found: ${req.method} ${req.originalUrl}`);
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found'
  });
});

// Global error handler
app.use((error, req, res, next) => {
  logger.error('Unhandled error:', error);

  // Don't expose stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(500).json({
    error: 'Internal Server Error',
    message: isProduction 
      ? 'An unexpected error occurred'
      : error.message,
    stack: isProduction ? undefined : error.stack
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  logger.info(`Server started on port ${PORT}`);
});

module.exports = app;

