const colors = {
  error: '\x1b[31m', // red
  warn: '\x1b[33m', // yellow
  info: '\x1b[32m', // green
  debug: '\x1b[36m', // cyan
  reset: '\x1b[0m' // reset
};

const logger = {
  error: (message, error) => {
    const timestamp = new Date().toISOString();
    console.error(`$\{colors.error}ERROR$\{colors.reset}} [$\{timestamp}] $\{message}`);

    if (error && error.stack) {
      console.error(error.stack);
    }
  },

  warn: (message) => {
    const timestamp = new Date().toISOString();
    console.warn(`$\{colors.warn}WARN $\{colors.reset}} [$\{timestamp}] $\{message}`);
  },

  info: (message) => {
    const timestamp = new Date().toISOString();
    console.log(`$\{colors.info}INFO $\{colors.reset}} [$\{timestamp}] $\{message}`);
  },

  debug: (message) => {
    if (process.env.NODE_ENV === 'development') {
      const timestamp = new Date().toISOString();
      console.log(`$\{colors.debug}DEBUG$\{colors.reset}} [$\{timestamp}] $\{message}`);
    }
  }
};

module.exports = logger;

