const axios = require('axios');

// Test database connection
async function testDatabaseConnection() {
  console.log('Testing database connection...');

  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log('❌ DATABASE_URL not found in .env.test');
    return false;
  }

  // Extract credentials from URL for display (hide actual password)
  const url = new URL(dbUrl);
  const maskedUrl = `${url.protocol}//${url.username}:***@${url.hostname}${url.pathname}`;
  console.log(`Attempting to connect to: ${maskedUrl}`);

  const client = new Client({ connectionString: dbUrl });

  try {
    await client.connect();
    await client.query('SELECT NOW()');
    await client.end();
    console.log('✅ Database connection successful');
    return true;
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);
    return false;
  }
}

// Test API key endpoints
async function testAnthropicApiKey() {
  console.log('\nTesting Anthropic API key...');

  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not found in .env.test');
    return false;
  }

  console.log('Attempting to validate Anthropic API key...');

  try {
    const response = await axios.post(
      'https://api.anthropic.com/v1/complete',
      {},
      {
        headers: {
          'x-api-key': apiKey,
          'Content-Type': 'application/json',
          'anthropic-version': '2023-06-01'
        }
      }
    );

    console.log('✅ Anthropic API key appears to be valid');
    return true;
  } catch (error) {
    if (error.response) {
      console.log(`❌ Anthropic API returned error: ${error.response.status} ${error.response.statusText}`);
    } else {
      console.log(`❌ Anthropic API request failed: ${error.message}`);
    }
    return false;
  }
}

// Test AWS credentials
async function testAwsCredentials() {
  console.log('\nTesting AWS credentials...');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS credentials not found in .env.test');
    return false;
  }

  console.log('Attempting to validate AWS credentials with STS...');

  // Note: This is a simplified test - a real implementation would use AWS SDK
