  const keyValid = /^AKIA[0-9A-Z]{16}$/.test(accessKeyId);
  const secretValid = secretAccessKey.length >= 40;

  if (keyValid && secretValid) {
    console.log('✅ AWS credentials have valid format');
    return true;
  } else {
    console.log('❌ AWS credentials have invalid format');
    return false;
  }
