  } catch (error) {
    if (error.response) {
      console.log(`❌ Stripe API returned error: ${error.response.status} ${error.response.statusText}`);
    } else {
      console.log(`❌ Stripe API request failed: ${error.message}`);
    }
    return false;
  }
}

// Test Logfire token
async function testLogfireToken() {
  console.log('\nTesting Logfire token...');

  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not found in .env.test');
    return false;
  }

  console.log('Attempting to validate Logfire token...');

  try {
    const response = await axios.get(
