const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());
app.use(helmet.hidePoweredBy());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    code: 'RATE_LIMIT_EXCEEDED'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// JSON body parser with security limits
app.use(express.json({
  limit: '10kb', // Prevent large payload attacks
  verify: (req, res, buf) => {
    req.rawBody = buf.toString();
  }
}));

// Input validation middleware for users endpoint
const validateUsersQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),

  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a positive integer')
    .toInt(),

  query('search')
    .optional()
    .isString()
    .isLength({ max: 100 })
    .withMessage('Search query too long')
];

// Improved health endpoint with proper error handling
app.get('/health', [
  rateLimit({
    windowMs: 60 * 1000,
    max: 10,
    message: {
      error: 'Health check rate limit exceeded',
      code: 'RATE_LIMIT_EXCEEDED'
    }
  })
], (req, res) => {
  try {
    const healthData = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      nodeVersion: process.version
    };

    res.json(healthData);
  } catch (error) {
    // This should never be reached, but here for completeness
    res.status(500).json({
      error: 'Health check failed',
      code: 'HEALTH_CHECK_FAILED'
    });
  }
});

// Improved users endpoint with validation and error handling
app.get('/users', validateUsersQuery, (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      code: 'VALIDATION_ERROR',
      details: errors.array()
    });
  }

  try {
    // Sample user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Extract query parameters with defaults
    const { limit = users.length, offset = 0, search } = req.query;

    // Filter users if search query is provided
    let filteredUsers = users;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    // Return response with metadata
    res.json({
      data: paginatedUsers,
      count: paginatedUsers.length,
      total: filteredUsers.length,
      offset,
      limit,
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Error in /users endpoint:', error);

    // Distinguish between different error types for appropriate response
    if (error.name === 'ValidationError') {
      return res.status(400).json({
        error: 'Invalid request parameters',
        code: 'VALIDATION_ERROR'
      });
    }

    // Generic error response to avoid leaking information
    res.status(500).json({
      error: 'An unexpected error occurred',
      code: 'INTERNAL_SERVER_ERROR'
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err);

  // Set locals, only providing error details in development
  res.locals.message = err.message;
  res.locals.error = req.app.get('env') === 'development' ? err : {};

  // Send error response
  res.status(err.status || 500).json({
    error: 'An unexpected error occurred',
    code: 'INTERNAL_SERVER_ERROR'
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    code: 'NOT_FOUND'
  });
});

// Graceful shutdown
const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
  console.log('Press Ctrl+C to exit');
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

