const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
require('dotenv').config();

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000']
}));
app.use(express.json({
  limit: '10kb'
}));

// Input validation middleware
const validateIdParam = (req, res, next) => {
  const id = req.params.id;
  if (!id) {
    return res.status(400).json({ error: 'ID parameter is required' });
  }

  const idNum = parseInt(id, 10);
  if (isNaN(idNum) || idNum <= 0) {
    return res.status(400).json({ error: 'ID must be a positive integer' });
  }

  req.params.id = idNum;
  next();
};

// Environment configuration
const PORT = parseInt(process.env.PORT, 10) || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Enhanced health check with environment info
app.get('/health', (req, res) => {
  // Remove sensitive info from health check in production
  if (NODE_ENV === 'production') {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } else {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: NODE_ENV,
      port: PORT
    });
  }
});

// Users endpoint with improved error handling
app.get('/users', (req, res) => {
  try {
    // In a real app, this would come from a database with proper error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Add filtering capability with validation
    const { name } = req.query;
    let filteredUsers = users;

    if (name) {
      // Basic input sanitization
      const sanitizedSearch = name.toString().trim().toLowerCase();
      if (sanitizedSearch.length > 0) {
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(sanitizedSearch)
        );
      }
    }

    res.json({
      count: filteredUsers.length,
      data: filteredUsers
    });

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error'
    });
  }
});

// Parameterized route with validation
app.get('/users/:id', validateIdParam, (req, res) => {
  try {
    const { id } = req.params;
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({ 
        error: `User with ID ${id} not found` 
      });
    }

    res.json(user);

  } catch (error) {
    console.error(`Error fetching user ${req.params.id}:`, error);
    res.status(500).json({ 
      error: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Hide detailed error messages in production
  if (NODE_ENV === 'production') {
    res.status(500).json({
      error: 'Internal server error'
    });
  } else {
    res.status(500).json({
      error: error.message,
      stack: error.stack
    });
  }
});

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  console.log(`Health check: http://localhost:${PORT}/health`);
  console.log(`Users: http://localhost:${PORT}/users`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received: shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received: shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

